    /* 2. Fluent UIのシステム変数を上書きして背景を透過させる */
    :root {
        /* 全体のメイン背景 */
        --colorNeutralBackground1: transparent !important;
        --m365-copilot-canvas-background: transparent !important;
        
        /* チャットエリアやサイドバー等の背景（視認性確保のため少し色を残す場合はrgbaを調整） */
        --colorNeutralBackground2: rgba(255, 255, 255, 0.4) !important; 
        --colorNeutralBackground3: rgba(255, 255, 255, 0.4) !important;
        --colorNeutralBackground4: rgba(255, 255, 255, 0.5) !important;
    }

    /* ダークモード環境への対応（もしダークモードを使っている場合） */
    [data-theme="dark"] {
        --colorNeutralBackground2: rgba(0, 0, 0, 0.4) !important; 
        --colorNeutralBackground3: rgba(0, 0, 0, 0.4) !important;
        --colorNeutralBackground4: rgba(0, 0, 0, 0.5) !important;
    }

    /* 3. 新しいレイアウトの主要コンテナを透過 */
    #m365-copilot-app-layout-root,
    #m365-copilot-app-layout-main,
    .fui-FluentProvider,
    .fai-CopilotProvider {
        background: transparent !important;
    }

    /* 4. メニューや入力エリアなど、操作に必要なUIの視認性確保 */
    nav,
    header,
    .fui-NavDrawer,
    .fui-NavDrawerHeader,
    div[class*="ReactShellMeControlContainer"] {
        background-color: rgba(255, 255, 255, 0.7) !important;
        backdrop-filter: blur(4px) !important; /* すりガラス効果で文字を読みやすく */
        z-index: 10 !important;
    }
    
    [data-theme="dark"] nav,
    [data-theme="dark"] header,
    [data-theme="dark"] .fui-NavDrawer,
    [data-theme="dark"] .fui-NavDrawerHeader {
        background-color: rgba(0, 0, 0, 0.7) !important;
    }

    /* 5. 念のための旧クラスと動的クラスの透過（元の設定を継承） */
